package uz.vocabkun.app;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.io.*;import java.util.*;
public class ReminderReceiver extends BroadcastReceiver {
 static PendingIntent pending(Context c){Intent i=new Intent(c,ReminderReceiver.class);int f=PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0);return PendingIntent.getBroadcast(c,7,i,f);}
 static void schedule(Context c,int mins){MainActivity.ensureChannel(c);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent pi=pending(c);long when=System.currentTimeMillis()+mins*60_000L;if(Build.VERSION.SDK_INT>=23)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else am.set(AlarmManager.RTC_WAKEUP,when,pi);}
 public void onReceive(Context c,Intent i){MainActivity.ensureChannel(c);android.content.SharedPreferences p=c.getSharedPreferences("vk",0);if(!p.getBoolean("enabled",false))return;String en="Learn",uz="o‘rganmoq";try{InputStream in=c.getAssets().open("words.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);JSONArray a=new JSONArray(out.toString("UTF-8"));JSONObject w=a.getJSONObject(new Random().nextInt(a.length()));en=w.optString("en",en);uz=w.optString("uz",uz);}catch(Exception ignored){}
 Notification.Builder nb=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"vocabkun_words"):new Notification.Builder(c);nb.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("VocabKun · "+en).setContentText(uz).setAutoCancel(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%100000),nb.build());schedule(c,p.getInt("interval",10));}
}
